-- ENDIVIDAMENTO: status conforme o modulo de ACC (liquidados la e ainda A LIQUIDAR aqui).
UPDATE "hedge_registros" SET "dados" = jsonb_set("dados", '{status}', '"LIQUIDADO"'), "updatedAt" = CURRENT_TIMESTAMP WHERE "aba" = 'endividamento-nayme' AND "dados"->>'numContrato' = '595571717' AND "dados"->>'status' = 'A LIQUIDAR';
