UPDATE "hedge_registros" SET "dados" = jsonb_set("dados", '{status}', '"LIQUIDADO"'), "updatedAt" = CURRENT_TIMESTAMP WHERE "aba" = 'endividamento-nayme' AND "dados"->>'numContrato' = '6005112097' AND "dados"->>'status' = 'A LIQUIDAR';
UPDATE "hedge_registros" SET "dados" = jsonb_set("dados", '{status}', '"LIQUIDADO"'), "updatedAt" = CURRENT_TIMESTAMP WHERE "aba" = 'endividamento-nayme' AND "dados"->>'numContrato' = '611563491' AND "dados"->>'status' = 'A LIQUIDAR';
-- ENDIVIDAMENTO: ACCs contratados depois da ultima conciliacao, com os dados do modulo de ACC.
) v(id, aba, ordem, dados, c, u) WHERE NOT EXISTS (SELECT 1 FROM "hedge_registros" h WHERE h."aba" = 'endividamento-nayme' AND h."dados"->>'numContrato' = (v.dados->>'numContrato'));

-- Cadastros (listas de selecao): inclui os valores novos usados nos lancamentos.
SELECT gen_random_uuid()::text, 'cadastro:' || n.cadastro,
       COALESCE((SELECT MAX(h."ordem") FROM "hedge_registros" h WHERE h."aba" = 'cadastro:' || n.cadastro), 0)
         + ROW_NUMBER() OVER (PARTITION BY n.cadastro ORDER BY n.nome)::int,
       jsonb_build_object('nome', n.nome), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (
  SELECT DISTINCT c.cadastro, CASE WHEN c.cadastro = 'corretoras-ndf' THEN UPPER(TRIM(r."dados"->>c.campo)) ELSE TRIM(r."dados"->>c.campo) END AS nome
  FROM "hedge_registros" r
  JOIN (VALUES ('compras-em-reais-nayme', 'produtores', 'produtor'), ('compras-em-reais-nayme', 'padroes', 'padrao'),
               ('compras-em-reais-nayme', 'peneiras', 'peneira'), ('trava-ndf-us-nayme', 'corretoras-ndf', 'corretora')) AS c(aba, cadastro, campo)
    ON r."aba" = c.aba
  WHERE COALESCE(TRIM(r."dados"->>c.campo), '') <> ''
) n
WHERE NOT EXISTS (
  SELECT 1 FROM "hedge_registros" h WHERE h."aba" = 'cadastro:' || n.cadastro AND h."dados"->>'nome' = n.nome
);
